public struct SyntaxChildrenIndex: Hashable, Comparable, Sendable {
  /// The index in a `SyntaxDataReferenceBuffer` that is being referenced by this `SyntaxChildrenIndex`.
  let value: Int

  init(value: Int) {
    self.value = value
  }

  /// Returns `true` if `lhs` occurs before `rhs`.
  public static func < (lhs: SyntaxChildrenIndex, rhs: SyntaxChildrenIndex) -> Bool {
    lhs.value < rhs.value
  }
}
extension PackageTarget.PluginUsage: ManifestSyntaxRepresentable {
  func asSyntax() -> ExprSyntax {
    switch self {
    case .plugin(let name, package: nil):
      return ".plugin(name: \(literal: name))"

    case .plugin // c
(let name, let package):
      return ".plugin(name: \(literal: name), package: \(literal: package))"
    }
  }
}

